        torqueSpecs: [ { part: "Engine Oil Drain Plug", value: "30 Nm", note: "Always use a new copper crush washer." }, { part: "Glow Plugs", value: "15 Nm", note: "DANGER: Soak in penetrant; remove strictly on a fully hot engine to avoid snapping." }, { part: "Injector Hold-Down Bolts", value: "7 Nm + 90 degrees", note: "CRITICAL: Single-use stretch bolts. Threads must be spotless." }, { part: "Wheel Bolts", value: "110 Nm", note: "Crisscross pattern." }, { part: "Valve Cover Bolts", value: "9 Nm", note: "Tighten evenly." }, { part: "Belt Tensioner Bolt", value: "35 Nm", note: "Requires offset tools." }, { part: "Manual Transmission Drain", value: "40 Nm", note: "Loosen fill plug first." }, { part: "Automatic Transmission Pan", value: "8 Nm", note: "Do not overtighten." }, { part: "Front Strut Top Nut", value: "60 Nm", note: "Use pass-through socket." }, { part: "Rear Shock Lower Mount", value: "85 Nm", note: "Tighten at normal ride height." } ],
        engineeringData: { blockDesign: "Inline-4, Heavy cast-iron block with aluminum cylinder head. Tilted 59 degrees forward to slide under the W168 sandwich floor. Incredible internal integrity, disastrous packaging.", crankshaft: "Forged Steel, 5 main bearings, massively overbuilt for the low power output.", pistonSpeed: "10.4 m/s @ 4000 RPM.", alternator: "90A/150A Water-Cooled Bosch (Deeply buried, highly prone to coolant leaks).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with an internal oil cooling gallery to manage diesel EGTs.", wristPinDiameter: "26 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M9.", crankMainJournal: "55.0 mm.", crankRodJournal: "48.0 mm.", rodRatio: "1.58." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "16-valve DOHC. Excellent airflow characteristics.", valveSizes: "Intake: 28.5 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel profile.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Suffers from severe injector seat erosion if washers fail and Black Death occurs." }, oilAndCooling: { oilSquirters: "Yes, 4x under-piston cooling jets.", oilPumpType: "Chain-driven gerotor.", thermostatOpening: "87°C Mechanical.", oilCooler: "Standard water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch EDC15 Common Rail.", maxPressure: "1350 Bar.", injectors: "Bosch Solenoid." }, tuningLimits: { maxSafeTorqueStock: "260 Nm", maxSafePowerStock: "115 hp", maxSafeRPM: "4500 RPM", weakestLink: "Wastegate Turbo flow limit, Injector Seals." }, electrical: { coils: "N/A", ecu: "Bosch EDC 15C0" } },
