          fluidsAndDrivetrain: [ { interval: "80,000 km", timeLimit: "8 years", task: "Manual Trans Fluid", details: "Drain and refill 75W-80.", parts: ["1.8L 75W-80"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "60,000 km", timeLimit: "6 years", task: "Auto Trans Fluid", details: "Drain, refill, replace filter.", parts: ["6.0L Dexron III", "Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4.", parts: ["1.0L DOT 4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "60,000 km", timeLimit: "4 years", task: "Coolant Flush", details: "Flush cooling system.", parts: ["6.0L MB 325.0"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "60,000 km", timeLimit: "6 years", task: "Power Steering Fluid", details: "Top up Pentosin.", parts: ["CHF 11S"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "60,000 km", timeLimit: "6 years", task: "Clutch Fluid", details: "Bleed manual clutch line.", parts: ["DOT 4"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "30 EUR" } ],
          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Engine Oil Change", details: "CRITICAL: Protects turbo.", parts: ["4.5L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Engine Air Filter", details: "Replace panel filter.", parts: ["Mann Air Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Filter", details: "Replace interior filter.", parts: ["Mahle Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Fuel Filter", details: "CRITICAL: Protects high pressure pump.", parts: ["Mahle Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" } ],
          ignitionAndEngine: [ { interval: "Every 10,000 km", timeLimit: "N/A", task: "Black Death Inspection", details: "CRITICAL: Inspect for leaking injector seals.", parts: ["N/A"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Belt & Tensioner", details: "CRITICAL: Replace belt drive.", parts: ["INA Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Water Pump", details: "Replace concurrently with tensioner.", parts: ["Pierburg Pump"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "120 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs", details: "Replace on HOT engine.", parts: ["4x Beru"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "Clear Fuel Lines", details: "Replace rubber O-rings to stop air leaks.", parts: ["Viton O-Rings"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "20 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "EGR Cleaning", details: "Scrape soot out of EGR/intake.", parts: ["Gaskets"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "10 EUR" } ],
          preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "N/A", task: "Rear Trailing Arm Bearings", details: "CRITICAL: Rebuild rusted bearings.", parts: ["Lemförder Kit"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "150 EUR" }, { interval: "Annually", timeLimit: "1 year", task: "Rust Inspection", details: "CRITICAL: Apply cavity wax heavily.", parts: ["Cavity Wax"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Front Control Arms", details: "Replace bushings/ball joints.", parts: ["Lemförder Arms"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "As Needed", timeLimit: "N/A", task: "Starter Motor", details: "Requires subframe drop.", parts: ["Bosch Starter"], importance: "Medium", laborDifficulty: "Expert", estimatedCost: "650 EUR" } ],
