            { interval: "100,000 km", timeLimit: "10 years", task: "Front Control Arm Bushings", details: "Replace the lower control arms to cure vague steering and uneven tire wear.", parts: ["Lemförder Control Arms"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" },
            { interval: "Annually", timeLimit: "1 year", task: "Door Seam Rust Inspection", details: "CRITICAL: Inspect the bottom edges of all doors and the tailgate. Apply cavity wax heavily to halt seam rust.", parts: ["Cavity Wax"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "25 EUR" },
            { interval: "As Needed", timeLimit: "Unlimited", task: "Starter Motor Replacement", details: "If the engine cranks slowly, the starter is failing. WARNING: Requires dropping the entire front subframe and engine.", parts: ["Bosch Starter Motor"], importance: "Medium", laborDifficulty: "Expert", estimatedCost: "800+ EUR (Labor)" }
